{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would require LEAs to classify school nurses they employ as licensed personnel and pay them under the LEA’s licensed-personnel salary schedule.",
      "rationale": "Conveys both required classification and compensation under the LEA’s licensed-personnel salary schedule, limited to employed nurses."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would not restrict an LEA’s ability to contract with the Tennessee public school nurse program for school health services or set contract terms, including nurse compensation. Its pay requirements would not apply to LEA contractors.",
      "rationale": "Covers the preserved contracting authority, discretion over contract terms and compensation, and exclusion of contractor compensation."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "An employed school nurse with a registered nurse license, Nationally Certified School Nurse credentials, and zero years of experience would receive the same base salary as a licensed teacher with a bachelor’s degree and zero years of experience.",
      "rationale": "Identifies the employment, licensing, certification, and experience conditions and the correct teacher base-salary benchmark. The named credential sufficiently identifies the certification requirement."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Employed nurses with more training and experience would receive more than that base salary",
      "rationale": "Conveys the required higher salary for employed nurses exceeding the previously described training and experience benchmark."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Employed nurses with more training and experience would receive more than that base salary; those with less would receive less.",
      "rationale": "Conveys the required lower salary for employed nurses with less training and experience than the previously described benchmark."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Adopting a salary schedule could not reduce the salary of a school nurse employed by the LEA at that time.",
      "rationale": "Covers the prohibition on salary reductions and the requirement that the nurse be employed when the schedule is adopted."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "It would take effect July 1, 2026, and apply beginning with the 2026–2027 school year.",
      "rationale": "States the effective date and conveys ongoing applicability beginning with the specified school year."
    }
  ]
}
